@Test
public void testAbbreviateMiddle_1_oe() {
    Object a = StringUtils.abbreviateMiddle(null, null, 0);
    assertNull(a);
}

mut_method_definition:
public static String abbreviateMiddle(final String str, final String middle, final int length) {
        if (isAnyEmpty(str, middle) || length >= str.length() || length < middle.length()+2) {
            return str;
        }

        final int targetSting = length-middle.length();
        final int startOffset = targetSting/2+targetSting%2;
        final int endOffset = str.length()-targetSting/2;

        return str.substring(0, startOffset) +
            middle +
            str.substring(endOffset);
    }

