@Test
public void testCreatePrimitiveArray_1_oe() {
    Object a = ArrayUtils.toPrimitive((Object[]) null);
    assertNull(a);
}

mut_docstring:
/**
     * <p>Converts an array of object Booleans to primitives.
     *
     * <p>This method returns {@code null} for a {@code null} input array.
     *
     * @param array  a {@code Boolean} array, may be {@code null}
     * @return a {@code boolean} array, {@code null} if null array input
     * @throws NullPointerException if array content is {@code null}
     */

mut_method_definition:
public static boolean[] toPrimitive(final Boolean[] array) {
        if (array == null) {
            return null;
        } else if (array.length == 0) {
            return EMPTY_BOOLEAN_ARRAY;
        }
        final boolean[] result = new boolean[array.length];
        for (int i = 0; i < array.length; i++) {
            result[i] = array[i].booleanValue();
        }
        return result;
    }

test_prefix:
@Test
public void testCreatePrimitiveArray_2_oe() {
    boolean[] a = new boolean[]{true};
    assertArrayEquals(a, ArrayUtils.toPrimitive(new Boolean[]{true}));
}

